  1	export interface Customer {
  2	  yearsWithMHPCO: number;
  3	}
  4	
  5	export interface Item {
  6	  type: string;
  7	  material?: string;
  8	  enchantment?: number;
  9	  cursed?: boolean;
 10	}
 11	
 12	// One entry of the MHPCO price list. The two published figures are quoted
 13	// independently: the office prints them side by side and has never promised that one
 14	// follows the other, so neither is derived from the other here.
 15	interface PriceListEntry {
 16	  insuranceValue: number;
 17	  basePremium: number;
 18	}
 19	
 20	// The MHPCO price list: the single statement of which item types the office insures at
 21	// all and what each of them is worth and costs. Main items are listed individually.
 22	const MAIN_ITEM_PRICE_LIST: Record<string, PriceListEntry> = {
 23	  sword: { insuranceValue: 1000, basePremium: 100 },
 24	  amulet: { insuranceValue: 600, basePremium: 60 },
 25	  staff: { insuranceValue: 800, basePremium: 80 },
 26	  potion: { insuranceValue: 400, basePremium: 40 },
 27	};
 28	
 29	// Components (e.g. runes, moonstones) are not individually price-listed: they all share
 30	// one tariff, so the component roster is the single source of which types are components
 31	// and what each of them is worth and costs.
 32	const COMPONENT_TYPES = ["rune", "moonstone"];
 33	const COMPONENT_PRICE: PriceListEntry = { insuranceValue: 250, basePremium: 25 };
 34	
 35	const PRICE_LIST: Record<string, PriceListEntry> = {
 36	  ...MAIN_ITEM_PRICE_LIST,
 37	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_PRICE])),
 38	};
 39	
 40	// What the MHPCO is willing to insure at all: only item types on its price list. The
 41	// acceptance rule is enforced at the lookup every price enquiry must pass through, so no
 42	// part of a declined cover can be priced or covered by any route.
 43	function listedPrice(type: string): PriceListEntry {
 44	  const price = PRICE_LIST[type];
 45	  if (price === undefined) {
 46	    throw new Error(`MHPCO does not insure items of type "${type}"`);
 47	  }
 48	  return price;
 49	}
 50	
 51	const BLOCK_SIZE = 3;
 52	const BLOCK_BASE_PREMIUM = 60;
 53	
 54	// MHPCO reading of "alike": two items are alike exactly when their types match,
 55	// not merely when they belong to the same family (rune-y, gemstone-y).
 56	function countAlikeItems(items: Item[]): Map<string, number> {
 57	  const counts = new Map<string, number>();
 58	  for (const item of items) {
 59	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
 60	  }
 61	  return counts;
 62	}
 63	
 64	// A building block is offered for exactly 3 alike components.
 65	function blockOfferApplies(type: string, count: number): boolean {
 66	  return COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE;
 67	}
 68	
 69	function typeBasePremium(type: string, count: number): number {
 70	  if (blockOfferApplies(type, count)) {
 71	    return BLOCK_BASE_PREMIUM;
 72	  }
 73	  return count * listedPrice(type).basePremium;
 74	}
 75	
 76	function policyBasePremium(items: Item[]): number {
 77	  let total = 0;
 78	  for (const [type, count] of countAlikeItems(items)) {
 79	    total += typeBasePremium(type, count);
 80	  }
 81	  return total;
 82	}
 83	
 84	const CURSE_SURCHARGE = 0.5;
 85	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
 86	const SURCHARGED_ENCHANTMENT_LEVEL = 5;
 87	
 88	// An item that carries no enchantment level at all is not enchanted: the MHPCO rates it
 89	// at level 0. Runes and moonstones are the usual such items. Both the premium-side and
 90	// the claim-side enchantment clauses read a level through here, so neither can disagree
 91	// with the other about what an unenchanted item is.
 92	function enchantmentLevel(item: Item): number {
 93	  return item.enchantment ?? 0;
 94	}
 95	
 96	// The enchantment level from which the MHPCO rates an item as a heightened risk worth a
 97	// premium surcharge. Deliberately a lower bar than the level at which the claim side
 98	// halves a reimbursement: charging more for enchantment and paying out less for it are
 99	// two clauses with their own thresholds, and neither follows the other when it moves.
100	function isEnchantedEnoughToSurcharge(item: Item): boolean {
101	  return enchantmentLevel(item) >= SURCHARGED_ENCHANTMENT_LEVEL;
102	}
103	
104	// Each risk factor the MHPCO recognises contributes its own rate; a cursed and
105	// highly enchanted item is assessed both surcharges.
106	function riskSurchargeRate(item: Item): number {
107	  return (
108	    (item.cursed === true ? CURSE_SURCHARGE : 0) +
109	    (isEnchantedEnoughToSurcharge(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0)
110	  );
111	}
112	
113	// Item-scoped risk surcharges are assessed against the affected item's own listed
114	// base premium -- the block offer discounts the policy base premium only and does not
115	// lower the surcharge base. Each item is rated separately and the results are summed.
116	function itemScopedSurcharges(items: Item[]): number {
117	  return items.reduce(
118	    (total, item) => total + listedPrice(item.type).basePremium * riskSurchargeRate(item),
119	    0,
120	  );
121	}
122	
123	const FIRST_INSURANCE_SURCHARGE = 0.1;
124	const LOYALTY_DISCOUNT = 0.2;
125	const LOYALTY_YEARS = 2;
126	
127	// Long-standing means at least LOYALTY_YEARS years of business. A discount, so it
128	// enters the policy-scoped rate as a negative rate.
129	function loyaltyRate(customer: Customer): number {
130	  return customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT : 0;
131	}
132	
133	const FOLLOW_UP_DISCOUNT = 0.15;
134	
135	// Every contract after the customer's first earns the follow-up discount.
136	function followUpRate(previousContracts: number): number {
137	  return previousContracts > 0 ? -FOLLOW_UP_DISCOUNT : 0;
138	}
139	
140	// The MHPCO's policy-scoped tariff: each recognised policy-wide modifier contributes
141	// its own rate, and the rates are assessed together against the policy base premium.
142	//
143	// MHPCO reading of "a first insurance": the initial assessment is of the items newly
144	// brought in, not of the customer. Every quote is therefore a first insurance for the
145	// items it covers, so the surcharge is an unconditional term here -- it consults no
146	// customer history, and a long-standing customer on a follow-up contract is assessed
147	// it alongside the loyalty and follow-up discounts rather than instead of them.
148	function policyScopedRate(customer: Customer, previousContracts: number): number {
149	  return FIRST_INSURANCE_SURCHARGE + loyaltyRate(customer) + followUpRate(previousContracts);
150	}
151	
152	// Policy-scoped modifiers are assessed against the policy base premium alone -- the
153	// plain sum of the item base premiums, deliberately excluding item-scoped surcharges.
154	function policyScopedAdjustment(
155	  basePremium: number,
156	  customer: Customer,
157	  previousContracts: number,
158	): number {
159	  return basePremium * policyScopedRate(customer, previousContracts);
160	}
161	
162	const PROCESSING_FEE = 5;
163	
164	// Amounts are rounded in the MHPCO's favor, which means opposite directions on the two
165	// sides of the ledger: a premium the MHPCO collects rounds up, a payout it owes rounds
166	// down. Both tolerate the same floating-point slack so that an amount computed as
167	// exactly 197.5 or 350.5 is not pushed across the boundary by representation error.
168	const AMOUNT_PRECISION = 1e-9;
169	
170	function roundUpInMHPCOFavor(amount: number): number {
171	  return Math.ceil(amount - AMOUNT_PRECISION);
172	}
173	
174	// How the MHPCO closes a premium: the processing fee is added at the very end, after
175	// every percentage modifier, and only that final figure is rounded -- intermediate
176	// amounts stay fractional, and rounding always favours the MHPCO.
177	function closedPremium(modifiedPremium: number): number {
178	  return roundUpInMHPCOFavor(modifiedPremium + PROCESSING_FEE);
179	}
180	
181	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
182	  const basePremium = policyBasePremium(items);
183	  return closedPremium(
184	    basePremium +
185	      itemScopedSurcharges(items) +
186	      policyScopedAdjustment(basePremium, customer, previousContracts),
187	  );
188	}
