190	export interface Damage {
191	  itemType: string;
192	  amount: number;
193	}
194	
195	export interface Incident {
196	  cause: string;
197	  damages: Damage[];
198	}
199	
200	export interface ClaimSettlement {
201	  payout: number;
202	  remainingCap: number;
203	}
204	
205	const DEDUCTIBLE = 100;
206	const CAP_MULTIPLE = 2;
207	
208	// The insurance sum is the plain total of the insured items' values; block discounts and
209	// premium modifiers affect what the customer pays, never what the policy covers.
210	function insuranceSum(items: Item[]): number {
211	  return items.reduce((sum, item) => sum + listedPrice(item.type).insuranceValue, 0);
212	}
213	
214	// The MHPCO pays out at most twice the insurance sum over the life of a policy.
215	function policyCap(items: Item[]): number {
216	  return CAP_MULTIPLE * insuranceSum(items);
217	}
218	
219	function roundDownInMHPCOFavor(amount: number): number {
220	  return Math.floor(amount + AMOUNT_PRECISION);
221	}
222	
223	const HALVED_ENCHANTMENT_LEVEL = 8;
224	const HALVED_REIMBURSEMENT = 0.5;
225	
226	// Which insured items the MHPCO considers too enchanted to reimburse in full.
227	function isEnchantedEnoughToHalve(insured: Item): boolean {
228	  return enchantmentLevel(insured) >= HALVED_ENCHANTMENT_LEVEL;
229	}
230	
231	// How much of a reported damage the MHPCO recognises before the deductible: a special
232	// clause can reduce the recognised amount, and absent any clause the full damage counts.
233	//
234	// The dragon-material clause is deliberately absent rather than forgotten. "Damage to items
235	// made of dragon material is fully reimbursed" grants exactly what every unclassified item
236	// already gets here -- full recognition -- so on its own it is indistinguishable from the
237	// default, and where it meets the halving clause the halving clause wins. Dragon material
238	// therefore never changes a recognised amount: it is subsumed by the default when it
239	// applies alone and overridden when it does not. A branch for it would be unreachable by
240	// any observation, so the clause is recorded here instead of being coded. Should the MHPCO
241	// ever grant dragon material more than full reimbursement, the clause becomes observable
242	// and earns a branch -- and a precedence decision against halving -- at that point.
243	function reimbursableDamage(damage: Damage, insured: Item): number {
244	  if (isEnchantedEnoughToHalve(insured)) {
245	    return damage.amount * HALVED_REIMBURSEMENT;
246	  }
247	  return damage.amount;
248	}
249	
250	// Each damage event bears its own deductible, and the MHPCO never pays less than nothing.
251	function reimbursement(damage: Damage, insured: Item): number {
252	  return Math.max(reimbursableDamage(damage, insured) - DEDUCTIBLE, 0);
253	}
254	// A damage entry names an insured item by type, and each entry consumes one of the items
255	// of that type the policy covers. The MHPCO admits a claim only when every entry finds an
256	// item of its own: a damage naming an uninsured type, or more entries of a type than the
257	// policy covers, is declined and the whole claim is rejected.
258	function claimInsuredItem(damage: Damage, unclaimed: Item[]): Item {
259	  const index = unclaimed.findIndex((item) => item.type === damage.itemType);
260	  if (index === -1) {
261	    throw new Error(`MHPCO policy does not cover a further "${damage.itemType}" to claim for`);
262	  }
263	  return unclaimed.splice(index, 1)[0];
264	}
265	
266	function incidentReimbursement(damages: Damage[], items: Item[]): number {
267	  const unclaimed = [...items];
268	  return damages.reduce(
269	    (total, damage) => total + reimbursement(damage, claimInsuredItem(damage, unclaimed)),
270	    0,
271	  );
272	}
273	
274	// How the MHPCO closes a claim against its cap. The cap is a lifetime limit on the policy,
275	// so what this settlement may pay is bounded by what the cap had left beforehand -- the
276	// cap less everything the policy has already paid out. An over-cap claim is trimmed to the
277	// remainder rather than declined: the customer is paid what is left and the cap closes at
278	// zero. Whether a claim may exceed its remaining cap, and by what rule, is the MHPCO's own
279	// decision and moves independently of how a damage is valued.
280	function cappedSettlement(desired: number, remainingBefore: number): ClaimSettlement {
281	  const payout = Math.min(desired, remainingBefore);
282	  return { payout, remainingCap: remainingBefore - payout };
283	}
284	
285	export function claim(items: Item[], incident: Incident, alreadyPaid = 0): ClaimSettlement {
286	  return cappedSettlement(
287	    roundDownInMHPCOFavor(incidentReimbursement(incident.damages, items)),
288	    policyCap(items) - alreadyPaid,
289	  );
290	}

